-- DMC Progress ERP — 04: load DEMO data directly (fictional projects, all rows marked is_demo / R_seed).
-- Run in Supabase → SQL Editor. Safe to run again: it first removes the previous demo rows.
-- Dates were generated on 2026-10-29. To remove demo data later: Data screen → Remove demo data (admin), or run the two DELETE lines below.
begin;
-- workflow / audit triggers would reject history rows inserted outside the app; pause them for this load only
alter table public.projects disable trigger user;
alter table public.activities disable trigger user;
alter table public.progress_updates disable trigger user;
alter table public.notifications disable trigger user;
delete from public.notifications where id like 'R_seed%';
delete from public.progress_updates where activity_id in (select id from public.activities where is_demo);
delete from public.activities where is_demo;
delete from public.projects where is_demo;

